using System.Globalization;
using System.Text;

namespace RedMist.TimingCommon.NativeGen;

/// <summary>
/// Emits the Android side: immutable data classes with kotlinx.serialization JSON names
/// (<c>RedMistModels.kt</c>), MessagePack decoders over msgpack-core values that read the same
/// array slots the C# formatters write (<c>RedMistMsgPack.kt</c>), and patch application.
/// </summary>
internal sealed class KotlinEmitter(TypeCatalog catalog, string package)
{
    private const string Header =
        "// <auto-generated> by RedMist.TimingCommon.NativeGen from RedMist.TimingCommon. Do not edit.\n";

    public void Write(string directory)
    {
        Directory.CreateDirectory(directory);
        File.WriteAllText(Path.Combine(directory, "RedMistModels.kt"), Naming.Lf(Models()));
        File.WriteAllText(Path.Combine(directory, "RedMistMsgPack.kt"), Naming.Lf(MsgPack()));
    }

    // ----- Models -----

    private string Models()
    {
        var sb = new StringBuilder(Header);
        sb.AppendLine("@file:Suppress(\"unused\", \"RedundantSuppression\")");
        sb.AppendLine();
        sb.AppendLine($"package {package}");
        sb.AppendLine();
        sb.AppendLine("import kotlinx.serialization.KSerializer");
        sb.AppendLine("import kotlinx.serialization.SerialName");
        sb.AppendLine("import kotlinx.serialization.Serializable");
        sb.AppendLine("import kotlinx.serialization.descriptors.PrimitiveKind");
        sb.AppendLine("import kotlinx.serialization.descriptors.PrimitiveSerialDescriptor");
        sb.AppendLine("import kotlinx.serialization.descriptors.SerialDescriptor");
        sb.AppendLine("import kotlinx.serialization.encoding.Decoder");
        sb.AppendLine("import kotlinx.serialization.encoding.Encoder");
        sb.AppendLine("import java.time.Instant");
        sb.AppendLine("import java.time.LocalDateTime");
        sb.AppendLine("import java.time.OffsetDateTime");
        sb.AppendLine("import java.time.ZoneOffset");
        sb.AppendLine();

        sb.AppendLine("""
            /** .NET DateTime as ISO-8601. Values without an offset are treated as UTC, as the server sends them. */
            object DotNetInstantSerializer : KSerializer<Instant> {
                override val descriptor: SerialDescriptor = PrimitiveSerialDescriptor("DotNetInstant", PrimitiveKind.STRING)
                override fun serialize(encoder: Encoder, value: Instant) = encoder.encodeString(value.toString())
                override fun deserialize(decoder: Decoder): Instant = parseDotNetInstant(decoder.decodeString())
            }

            /** .NET DateTime.MinValue (0001-01-01), the value an unset C# DateTime member holds. */
            val DotNetMinInstant: Instant = Instant.parse("0001-01-01T00:00:00Z")

            fun parseDotNetInstant(text: String): Instant =
                runCatching { OffsetDateTime.parse(text).toInstant() }
                    .recoverCatching { LocalDateTime.parse(text).toInstant(ZoneOffset.UTC) }
                    .getOrThrow()

            """);

        foreach (var e in catalog.Enums)
            WriteEnum(sb, e);
        foreach (var t in catalog.Classes)
            WriteClass(sb, t);
        foreach (var t in catalog.Classes.Where(c => c.PatchOf != null))
            WritePatchFunctions(sb, t);

        sb.AppendLine("/** JSON serializer for each model, by its C# name, for code that picks a type at runtime (tests, fixtures). */");
        sb.AppendLine("val redMistSerializers: Map<String, KSerializer<*>> = mapOf(");
        sb.AppendLine(string.Join(",\n", catalog.Classes.Select(t => $"    \"{t.Name}\" to {t.Name}.serializer()")));
        sb.AppendLine(")");

        return sb.ToString();
    }

    private static void WriteEnum(StringBuilder sb, EnumModel e)
    {
        var fallback = e.Members.FirstOrDefault(m => m.Value == 0);
        if (fallback.Name == null) fallback = e.Members[0];

        sb.AppendLine($"/** Sent as its integer value, like the C# enum. Unknown values read as {fallback.Name}. */");
        sb.AppendLine($"@Serializable(with = {e.Name}Serializer::class)");
        sb.AppendLine($"enum class {e.Name}(val value: Int) {{");
        sb.AppendLine(string.Join(",\n", e.Members.Select(m => $"    {m.Name}({m.Value})")) + ";");
        sb.AppendLine();
        sb.AppendLine("    companion object {");
        sb.AppendLine($"        fun fromValue(value: Int): {e.Name} = entries.firstOrNull {{ it.value == value }} ?: {fallback.Name}");
        sb.AppendLine("    }");
        sb.AppendLine("}");
        sb.AppendLine();
        sb.AppendLine($"object {e.Name}Serializer : KSerializer<{e.Name}> {{");
        sb.AppendLine($"    override val descriptor: SerialDescriptor = PrimitiveSerialDescriptor(\"{e.Name}\", PrimitiveKind.INT)");
        sb.AppendLine($"    override fun serialize(encoder: Encoder, value: {e.Name}) = encoder.encodeInt(value.value)");
        sb.AppendLine($"    override fun deserialize(decoder: Decoder): {e.Name} = {e.Name}.fromValue(decoder.decodeInt())");
        sb.AppendLine("}");
        sb.AppendLine();
    }

    private void WriteClass(StringBuilder sb, TypeModel t)
    {
        sb.AppendLine($"/** C# {t.Clr.FullName}. */");
        sb.AppendLine("@Serializable");
        sb.AppendLine($"data class {t.Name}(");
        var lines = t.Props.Select(p =>
        {
            var serializer = InstantSerializerAnnotation(p.ClrType);
            return $"    @SerialName(\"{p.JsonKey}\"){serializer} val {Naming.Member(p.Name)}: {KType(p.ClrType, p.IsNullable, p.ElementNullable)} = {Default(p)}";
        });
        sb.AppendLine(string.Join(",\n", lines));
        sb.Append(')');

        if (t.Consts.Count > 0)
        {
            sb.AppendLine(" {");
            sb.AppendLine("    companion object {");
            foreach (var c in t.Consts)
                sb.AppendLine($"        const val {ConstName(c.Name)}: {KType(c.ClrType, false)} = {Literal(c.Value, c.ClrType)}");
            sb.AppendLine("    }");
            sb.Append('}');
        }
        sb.AppendLine();
        sb.AppendLine();
    }

    private static string InstantSerializerAnnotation(Type t)
    {
        var u = Nullable.GetUnderlyingType(t) ?? t;
        return u == typeof(DateTime)
            ? " @Serializable(with = DotNetInstantSerializer::class)"
            : "";
    }

    private void WritePatchFunctions(StringBuilder sb, TypeModel patch)
    {
        var target = patch.PatchOf!;
        var patchProps = patch.Props.ToDictionary(p => p.Name);
        var shared = target.Props.Where(p => patchProps.ContainsKey(p.Name)).ToList();

        sb.AppendLine($"/** Applies the non-null fields of [patch], like the C# {target.Name}Mapper.ApplyPatch. */");
        sb.AppendLine($"fun {target.Name}.applyPatch(patch: {patch.Name}): {target.Name} = copy(");
        sb.AppendLine(string.Join(",\n", shared.Select(p =>
        {
            var m = Naming.Member(p.Name);
            return $"    {m} = patch.{m} ?: {m}";
        })));
        sb.AppendLine(")");
        sb.AppendLine();
        sb.AppendLine($"/** Every field of this {target.Name} as a patch, like the C# {target.Name}Mapper.CreatePatch from an empty state. */");
        sb.AppendLine($"fun {target.Name}.toPatch(): {patch.Name} = {patch.Name}(");
        sb.AppendLine(string.Join(",\n", shared.Select(p =>
        {
            var m = Naming.Member(p.Name);
            return $"    {m} = {m}";
        })));
        sb.AppendLine(")");
        sb.AppendLine();
    }

    // ----- MessagePack -----

    private string MsgPack()
    {
        var sb = new StringBuilder(Header);
        sb.AppendLine("@file:Suppress(\"unused\", \"RedundantSuppression\")");
        sb.AppendLine();
        sb.AppendLine($"package {package}");
        sb.AppendLine();
        sb.AppendLine("import org.msgpack.core.MessagePack");
        sb.AppendLine("import org.msgpack.value.ArrayValue");
        sb.AppendLine("import org.msgpack.value.MapValue");
        sb.AppendLine("import org.msgpack.value.Value");
        sb.AppendLine("import java.time.Instant");
        sb.AppendLine();
        sb.AppendLine("""
            /**
             * Decoders for the MessagePack the server writes. Keyed types are arrays indexed by the C#
             * [Key(n)] slots; a slot that is missing (an older sender) or nil reads as the default, and
             * extra slots (a newer sender) are ignored. Contractless types are maps of property names.
             */
            object RedMistMsgPack {
                fun unpack(bytes: ByteArray): Value = MessagePack.newDefaultUnpacker(bytes).use { it.unpackValue() }

            """);

        foreach (var t in catalog.Classes)
        {
            sb.AppendLine($"    fun decode{t.Name}(value: Value): {t.Name} {{");
            sb.AppendLine(t.IsKeyed
                ? "        val a = value.asArrayValue()"
                : "        val m = value.asMapValue().map().entries.associate { (k, v) -> k.asStringValue().asString() to v }");
            sb.AppendLine($"        return {t.Name}(");
            sb.AppendLine(string.Join(",\n", t.Props.Select(p =>
            {
                var slot = t.IsKeyed ? $"a.slot({p.Key})" : $"m[\"{p.MapKey}\"].orNil()";
                var expr = Decode(p.ClrType, "it", p.ElementNullable);
                var member = Naming.Member(p.Name);
                if (!p.IsNullable)
                    return $"            {member} = {slot}?.let {{ {expr} }} ?: {Default(p)}";
                // A nullable member with a non-null initializer: nil means null, but a slot an older
                // sender never wrote keeps the initializer, as in C#.
                if (p.DefaultValue != null && t.IsKeyed)
                    return $"            {member} = if (a.size() <= {p.Key}) {Default(p)} else {slot}?.let {{ {expr} }}";
                return $"            {member} = {slot}?.let {{ {expr} }}";
            })));
            sb.AppendLine("        )");
            sb.AppendLine("    }");
            sb.AppendLine();
        }

        sb.AppendLine("    /** MessagePack decoder for each model, by its C# name. */");
        sb.AppendLine("    val decoders: Map<String, (Value) -> Any> = mapOf(");
        sb.AppendLine(string.Join(",\n", catalog.Classes.Select(t => $"        \"{t.Name}\" to ::decode{t.Name}")));
        sb.AppendLine("    )");
        sb.AppendLine();

        sb.AppendLine("""
                private fun ArrayValue.slot(index: Int): Value? = if (index < size()) get(index).takeUnless { it.isNilValue } else null
                private fun Value?.orNil(): Value? = this?.takeUnless { it.isNilValue }

                private fun Value.int(): Int = asIntegerValue().toInt()
                private fun Value.long(): Long = asIntegerValue().toLong()
                private fun Value.double(): Double = if (isFloatValue) asFloatValue().toDouble() else asIntegerValue().toLong().toDouble()
                private fun Value.bool(): Boolean = asBooleanValue().boolean
                private fun Value.str(): String = asStringValue().asString()
                private fun Value.decimal(): Double = if (isStringValue) str().toDouble() else double()
                private fun Value.instant(): Instant = asTimestampValue().toInstant()

                /**
                 * TimeOnly is written as its tick count (100 ns since midnight). Returns the text
                 * System.Text.Json writes for the same value: "HH:mm:ss", plus ".fffffff" when there is a fraction.
                 */
                private fun Value.timeOnly(): String {
                    if (isStringValue) return str()
                    val ticks = long()
                    val totalSeconds = ticks / 10_000_000
                    val fraction = ticks % 10_000_000
                    fun two(n: Long) = n.toString().padStart(2, '0')
                    val base = two(totalSeconds / 3600) + ":" + two((totalSeconds / 60) % 60) + ":" + two(totalSeconds % 60)
                    return if (fraction == 0L) base else base + "." + fraction.toString().padStart(7, '0')
                }

                private fun <T> Value.list(item: (Value) -> T): List<T> = asArrayValue().map(item)
                private fun <K, V> Value.mapOf(key: (Value) -> K, item: (Value) -> V): Map<K, V> =
                    asMapValue().map().entries.associate { (k, v) -> key(k) to item(v) }
            }
            """);
        return sb.ToString();
    }

    private string Decode(Type type, string v, bool elementNullable = false)
    {
        type = Nullable.GetUnderlyingType(type) ?? type;
        if (type == typeof(int) || type == typeof(short) || type == typeof(ushort) || type == typeof(byte) || type == typeof(sbyte)) return $"{v}.int()";
        if (type == typeof(uint) || type == typeof(long) || type == typeof(ulong)) return $"{v}.long()";
        if (type == typeof(double) || type == typeof(float)) return $"{v}.double()";
        if (type == typeof(decimal)) return $"{v}.decimal()";
        if (type == typeof(bool)) return $"{v}.bool()";
        if (type == typeof(string)) return $"{v}.str()";
        if (type == typeof(DateTime)) return $"{v}.instant()";
        if (type == typeof(TimeOnly)) return $"{v}.timeOnly()";
        if (type.IsEnum) return $"{catalog.Names[type]}.fromValue({v}.int())";
        if (ElementType(type) is { } element)
            return elementNullable
                ? $"{v}.list {{ e -> if (e.isNilValue) null else {Decode(element, "e")} }}"
                : $"{v}.list {{ e -> {Decode(element, "e")} }}";
        if (IsDictionary(type, out var k, out var val))
            return elementNullable
                ? $"{v}.mapOf({{ k -> {Decode(k, "k")} }}, {{ e -> if (e.isNilValue) null else {Decode(val, "e")} }})"
                : $"{v}.mapOf({{ k -> {Decode(k, "k")} }}, {{ e -> {Decode(val, "e")} }})";
        if (catalog.IsClass(type)) return $"decode{catalog.Names[type]}({v})";
        throw new NotSupportedException($"No Kotlin MessagePack decoding for {type}");
    }

    // ----- Types and defaults -----

    private string KType(Type type, bool nullable, bool elementNullable = false)
    {
        var u = Nullable.GetUnderlyingType(type);
        if (u != null) return KType(u, false, elementNullable) + "?";
        var name = type switch
        {
            _ when type == typeof(int) || type == typeof(short) || type == typeof(ushort) || type == typeof(byte) || type == typeof(sbyte) => "Int",
            _ when type == typeof(uint) || type == typeof(long) || type == typeof(ulong) => "Long",
            _ when type == typeof(double) || type == typeof(float) || type == typeof(decimal) => "Double",
            _ when type == typeof(bool) => "Boolean",
            _ when type == typeof(string) || type == typeof(TimeOnly) => "String",
            _ when type == typeof(DateTime) => "Instant",
            _ when type.IsEnum => catalog.Names[type],
            _ when ElementType(type) is { } e => $"List<{KType(e, elementNullable && Nullable.GetUnderlyingType(e) == null)}>",
            _ when IsDictionary(type, out var k, out var v) => $"Map<{KType(k, false)}, {KType(v, elementNullable && Nullable.GetUnderlyingType(v) == null)}>",
            _ when catalog.IsClass(type) => catalog.Names[type],
            _ => throw new NotSupportedException($"No Kotlin type for {type}")
        };
        return nullable ? name + "?" : name;
    }

    private string Default(PropModel p)
    {
        if (p.IsNullable)
            return p.DefaultValue == null ? "null" : Default(p with { IsNullable = false, ClrType = Nullable.GetUnderlyingType(p.ClrType) ?? p.ClrType });
        var t = p.ClrType;
        if (ElementType(t) != null) return "emptyList()";
        if (IsDictionary(t, out _, out _)) return "emptyMap()";
        if (t == typeof(DateTime)) return "DotNetMinInstant";
        if (catalog.IsClass(t)) return $"{catalog.Names[t]}()";
        if (t.IsEnum)
        {
            var name = p.DefaultValue != null ? Enum.GetName(t, p.DefaultValue) : Enum.GetNames(t)[0];
            return $"{catalog.Names[t]}.{name}";
        }
        if (t == typeof(TimeOnly)) return "\"00:00:00\"";
        if (t == typeof(string)) return Literal(p.DefaultValue ?? "", t);
        return Literal(p.DefaultValue ?? Activator.CreateInstance(t), t);
    }

    private static string Literal(object? value, Type t) => value switch
    {
        null => "null",
        string s => "\"" + s.Replace("\\", "\\\\").Replace("\"", "\\\"").Replace("$", "\\$") + "\"",
        bool b => b ? "true" : "false",
        double d => d.ToString("R", CultureInfo.InvariantCulture) + (d % 1 == 0 && !double.IsInfinity(d) ? ".0" : ""),
        float f => ((double)f).ToString("R", CultureInfo.InvariantCulture) + (f % 1 == 0 ? ".0" : ""),
        decimal m => m.ToString(CultureInfo.InvariantCulture) + (m % 1 == 0 ? ".0" : ""),
        uint or long or ulong => Convert.ToString(value, CultureInfo.InvariantCulture) + "L",
        _ => Convert.ToString(value, CultureInfo.InvariantCulture)!,
    };

    private static string ConstName(string name) =>
        string.Concat(name.Select((c, i) => i > 0 && char.IsUpper(c) && !char.IsUpper(name[i - 1]) ? "_" + c : c.ToString())).ToUpperInvariant();

    internal static Type? ElementType(Type t)
    {
        if (t.IsArray) return t.GetElementType();
        if (t.IsGenericType && (t.GetGenericTypeDefinition() == typeof(List<>) || t.GetGenericTypeDefinition() == typeof(IList<>)
            || t.GetGenericTypeDefinition() == typeof(IReadOnlyList<>) || t.GetGenericTypeDefinition() == typeof(IEnumerable<>)
            || t.GetGenericTypeDefinition() == typeof(HashSet<>)))
            return t.GetGenericArguments()[0];
        return null;
    }

    internal static bool IsDictionary(Type t, out Type key, out Type value)
    {
        if (t.IsGenericType && (t.GetGenericTypeDefinition() == typeof(Dictionary<,>) || t.GetGenericTypeDefinition() == typeof(IDictionary<,>)
            || t.GetGenericTypeDefinition() == typeof(IReadOnlyDictionary<,>)))
        {
            key = t.GetGenericArguments()[0];
            value = t.GetGenericArguments()[1];
            return true;
        }
        key = value = typeof(void);
        return false;
    }
}
